test "every opcode carries metadata" {
    try std.testing.expectEqual(@as(usize, 456), op_info.len);
    try std.testing.expect(!Op.invalid.isValid());
    const add = Op.addx.info();
    try std.testing.expectEqual(@as(u6, 31), add.primary());
    try std.testing.expect(add.has_rc and add.has_oe);
    try std.testing.expectEqual(Form.xo, add.form);
    try std.testing.expectEqual(Group.integer, add.group);
    try std.testing.expect(Op.bx.info().ends_block);
}
